    @Test void unicodeReasonBoundaryAndStaleVersionCannotOverrideNewStage()throws Exception{var f=fixture();var id=prepared(f,"PRINTING");var at=login(user("ADMIN"));expect(close(id,at,"😀".repeat(301),"3"),400,"VALIDATION_FAILED");var mt=login(f.merchant().user());data(ready(mt,id));var before=facts(f,id);expect(close(id,at,"核实原因","3"),409,"CONFIG_VERSION_CONFLICT");assertThat(facts(f,id)).isEqualTo(before);data(close(id,at,"😀".repeat(300),"4"));}
    @ParameterizedTest @ValueSource(strings={"UNPAID","COMPLETED","USER_CLOSED","QUEUED_IN_SERVICE","NO_ACCEPTED","NO_STARTED","PICKED","COMPLETED_AT","WRONG_TIME"})
    void firstClosureCannotRepairInvalidOrTerminalStates(String state)throws Exception{var f=fixture();var id=prepared(f,state.equals("UNPAID")?"UNPAID":state.equals("COMPLETED")?"COMPLETED":state.equals("USER_CLOSED")?"CLOSED":"READY");var at=login(user("ADMIN"));switch(state){case "QUEUED_IN_SERVICE"->jdbc.update("UPDATE print_detail SET progress='QUEUED' WHERE order_id=?",id);case "NO_ACCEPTED"->jdbc.update("UPDATE service_order SET accepted_at=NULL WHERE id=?",id);case "NO_STARTED"->jdbc.update("UPDATE service_order SET started_at=NULL WHERE id=?",id);case "PICKED"->jdbc.update("UPDATE print_detail SET picked_up_at=? WHERE order_id=?",FileRules.utc(NOW),id);case "COMPLETED_AT"->jdbc.update("UPDATE service_order SET completed_at=? WHERE id=?",FileRules.utc(NOW),id);case "WRONG_TIME"->jdbc.update("UPDATE print_detail SET ready_at=? WHERE order_id=?",FileRules.utc(NOW.minusMillis(1)),id);}var before=facts(f,id);expect(close(id,at,"核实原因",version(f,id)),409,"ORDER_STATE_CONFLICT");assertThat(facts(f,id)).isEqualTo(before);}
    @ParameterizedTest @CsvSource({"PENDING_ACCEPTANCE,-1","PENDING_ACCEPTANCE,0","PENDING_ACCEPTANCE,1","ACCEPTED,-1","ACCEPTED,0","PRINTING,-1","PRINTING,0","READY,-1","READY,0","READY,1"})
    void closingInstantMustFollowSavedStage(String stage,long delta)throws Exception{fixed(NOW.minusSeconds(60));var f=fixture();var id=order(f);var at=login(user("ADMIN"));var mt=login(f.merchant().user());fixed(NOW);data(pay(f,id));if(!stage.equals("PENDING_ACCEPTANCE")){data(action(mt,id,"accept",null));if(!stage.equals("ACCEPTED")){data(start(mt,id));if(stage.equals("READY")){data(ready(mt,id));}}}var v=version(f,id);var before=facts(f,id);fixed(NOW.plusMillis(delta));var response=close(id,at,"核实原因",v);expect(response,delta<0?409:200,delta<0?"PRINT_TIME_INVALID":"OK");if(delta<0){assertThat(facts(f,id)).isEqualTo(before);}else{assertThat(data(response).path("closedAt").asString()).isEqualTo(NOW.plusMillis(delta).toString());}}
    @ParameterizedTest @ValueSource(strings={"REASON","VERSION","OTHER_ADMIN","DISABLED_ADMIN"})
    void onlyOriginalSuccessfulOperationCanReplay(String change)throws Exception{var f=fixture();var id=prepared(f,"READY");var a=user("ADMIN");var at=login(a);data(close(id,at,"核实原因","4"));String reason="核实原因",v="4";if(change.equals("REASON")){reason="另一原因";}else if(change.equals("VERSION")){v="5";}else if(change.equals("OTHER_ADMIN")){at=login(user("ADMIN"));}else{invalidate(a,"DISABLED");}var before=facts(f,id);expect(close(id,at,reason,v),change.equals("DISABLED_ADMIN")?403:409,change.equals("DISABLED_ADMIN")?"ACCOUNT_DISABLED":"ORDER_STATE_CONFLICT");assertThat(facts(f,id)).isEqualTo(before);}
