    void corruptedPersistedClosureFactsNeverReplayAsSuccess(String fault)throws Exception{var f=fixture();var id=prepared(f,"READY");var at=login(user("ADMIN"));data(close(id,at,"核实原因","4"));switch(fault){case "AMOUNT"->jdbc.update("UPDATE refund_record SET amount=amount+1 WHERE order_id=?",id);case "NOTE"->jdbc.update("UPDATE refund_record SET reason_note='other' WHERE order_id=?",id);case "REASON"->jdbc.update("UPDATE refund_record SET reason='USER_CANCEL' WHERE order_id=?",id);case "REFUND_TIME"->jdbc.update("UPDATE refund_record SET refunded_at=? WHERE order_id=?",FileRules.utc(NOW.plusSeconds(1)),id);case "EVENT_TIME"->jdbc.update("UPDATE order_event SET occurred_at=? WHERE order_id=? AND action='ADMIN_EXCEPTION'",FileRules.utc(NOW.plusSeconds(1)),id);case "PROGRESS"->jdbc.update("UPDATE print_detail SET progress='READY_FOR_PICKUP' WHERE order_id=?",id);}var before=facts(f,id);assertThat(close(id,at,"核实原因","4").statusCode()).isEqualTo(500);assertThat(facts(f,id)).isEqualTo(before);}
