    @ParameterizedTest @ValueSource(strings={"SAME","OTHER_ADMIN","START","READY","PICKUP","STUDENT_CANCEL","MERCHANT_CANCEL","EXPIRY"})
    void realMysqlCompetingActionsPreserveOneClosureOrCompletedFact(String race)throws Exception{String stage=switch(race){case "START","MERCHANT_CANCEL"->"ACCEPTED";case "READY"->"PRINTING";case "STUDENT_CANCEL","EXPIRY"->"PENDING_ACCEPTANCE";default->"READY";};var f=fixture();var id=prepared(f,stage);var at=login(user("ADMIN"));var other=login(user("ADMIN"));var mt=login(f.merchant().user());var v=version(f,id);if(race.equals("EXPIRY")){fixed(NOW.plusSeconds(1800));}var gate=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->{await(gate);return close(id,at,"核实原因",v);});var b=pool.submit(()->{await(gate);return switch(race){case "SAME"->close(id,at,"核实原因",v);case "OTHER_ADMIN"->close(id,other,"核实原因",v);case "START"->start(mt,id);case "READY"->ready(mt,id);case "PICKUP"->pickup(f,id);case "STUDENT_CANCEL"->cancel(f,id);case "MERCHANT_CANCEL"->action(mt,id,"cancel","{\"reason\":\"test\"}");default->{expiry.scan();yield null;}};});gate.countDown();var ar=a.get(20,TimeUnit.SECONDS);var br=b.get(20,TimeUnit.SECONDS);assertThat(ar.statusCode()).as(ar.body()).isIn(200,409);if(br!=null){assertThat(br.statusCode()).as(br.body()).isIn(200,409);if(race.equals("SAME")){assertThat(ar.statusCode()).isEqualTo(200);assertThat(br.statusCode()).isEqualTo(200);}else{assertThat(List.of(ar.statusCode(),br.statusCode())).containsExactlyInAnyOrder(200,409);}}}
        var current=detail(f,id);boolean closed="CLOSED".equals(current.path("status").asString());assertThat(count("refund_record",id)).isEqualTo(closed?1:0);if(Set.of("START","READY").contains(race)&&!closed){var before=facts(f,id);expect(close(id,at,"核实原因",v),409,"CONFIG_VERSION_CONFLICT");assertThat(facts(f,id)).isEqualTo(before);}if(race.equals("PICKUP")&&!closed){assertThat(current.path("status").asString()).isEqualTo("COMPLETED");}if(race.equals("EXPIRY")){assertThat(current.path("closeReason").asString()).isIn("ADMIN_EXCEPTION","ACCEPTANCE_TIMEOUT");}
    }
    @ParameterizedTest @ValueSource(strings={"SHOP","FILE","ORDER"})
    void decisionTimeAndCurrentViewFollowRealLockWait(String target)throws Exception{var f=fixture();var id=prepared(f,"READY");var at=login(user("ADMIN"));var held=new CountDownLatch(1);var release=new CountDownLatch(1);var entering=new CountDownLatch(1);var tx=new TransactionTemplate(manager);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var holder=pool.submit(()->tx.execute(s->{jdbc.queryForList(switch(target){case "SHOP"->"SELECT id FROM shop WHERE id=? FOR UPDATE";case "FILE"->"SELECT id FROM file_asset WHERE id=? FOR UPDATE";default->"SELECT id FROM service_order WHERE id=? FOR UPDATE";},switch(target){case "SHOP"->f.merchant().shop();case "FILE"->f.file().getId();default->Long.parseLong(id);});held.countDown();await(release);return null;}));await(held);if(target.equals("FILE")){var real=sqlSession.getMapper(FileAssetMapper.class);doAnswer(i->{entering.countDown();return real.lock(i.getArgument(0));}).when(files).lock(eq(f.file().getId()));}else{var real=sqlSession.getMapper(com.campuslife.order.mapper.OrderMapper.class);if(target.equals("SHOP")){doAnswer(i->{entering.countDown();return real.shareShop(i.getArgument(0));}).when(orderRows).shareShop(eq(f.merchant().shop()));}else{doAnswer(i->{entering.countDown();return real.lock(i.getArgument(0));}).when(orderRows).lock(eq(Long.parseLong(id)));}}var request=pool.submit(()->close(id,at,"核实原因","4"));await(entering);fixed(NOW.plusSeconds(10));release.countDown();holder.get(10,TimeUnit.SECONDS);var result=data(request.get(15,TimeUnit.SECONDS));assertThat(result.path("status").asString()).isEqualTo("CLOSED");assertThat(result.path("closedAt").asString()).isEqualTo(NOW.plusSeconds(10).toString());}finally{release.countDown();}}
